function PullWord(options) {
    this.defaultSettings = {
        url: 'http://api.pullword.com/post.php', /* api url */
        threshold: 0.5, /* 阀值 */
        debug: 0, /* 调式模式 */
        array: 1 /* 返回数组 */
    };

    this.init(options);
}
    // ...
PullWord.prototype.pullword = function(source, options, callback) {
    var _this = this;

    /* support overload */
    if (typeof options === 'function') {
        callback = options;
    }

    var settings = extend({}, _this.defaultSettings);

    if (typeof options === 'object') {
        extend(settings, options);
    }

    if (!source) {
        source = settings.debug || !settings.array ? '' : [];
        return callback(null, source);
    }

    var params = {
        url: settings.url,
        form: {
            source: source,
            param1: settings.threshold,
            param2: settings.debug ? 1 : 0 // support true or false
        }
    };

    request.post(params, _this.wrap(settings, callback));
};

